package com.example.jobpuzzle.analysis.service;
import com.example.jobpuzzle.analysis.entity.*; import com.example.jobpuzzle.analysis.repository.*; import com.example.jobpuzzle.guide.entity.*; import com.example.jobpuzzle.guide.repository.*; import com.example.jobpuzzle.interview.entity.*; import com.example.jobpuzzle.interview.repository.*; import com.example.jobpuzzle.jobcategory.entity.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.test.util.ReflectionTestUtils; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) @org.mockito.junit.jupiter.MockitoSettings(strictness=org.mockito.quality.Strictness.LENIENT) class CompanyFitQuestionSetQueryServiceTest { @Mock AnalysisCaseRepository cases; @Mock AnalysisInputSnapshotRepository snapshots; @Mock ReadinessResultRepository readiness; @Mock QuestionSetRepository sets; @Mock InterviewQuestionRepository questions; @Mock GuideContextResultRepository guides; @InjectMocks CompanyFitQuestionSetQueryService service; AnalysisCase c; AnalysisInputSnapshot s; ReadinessResult r; GuideContextResult g;
 @BeforeEach void set(){var cat=JobCategory.builder().mainCategory("IT").subCategory("BE").careerLevel(JobCategoryCareerLevel.NEW).build();c=AnalysisCase.builder().user(null).jobCategory(cat).build();ReflectionTestUtils.setField(c,"status",AnalysisCaseStatus.COMPLETED);s=mock(AnalysisInputSnapshot.class);when(s.getSnapshotId()).thenReturn(1L);r=mock(ReadinessResult.class);g=GuideContextResult.create(null,"1",cat,null,GuideMatchType.NONE);when(cases.findByAnalysisCaseIdAndUser_UserId(1L,1L)).thenReturn(Optional.of(c));when(snapshots.findByAnalysisCase_AnalysisCaseIdAndUser_UserId(1L,1L)).thenReturn(Optional.of(s));when(readiness.findBySnapshot_SnapshotId(1L)).thenReturn(Optional.of(r));when(guides.findByPurposeAndInputReferenceTypeAndInputReferenceId(any(),any(),eq("1"))).thenReturn(Optional.of(g));}
 @Test void limitedResultReturnsEmptyQuestionSetWithoutWrites(){when(r.isCanGenerateQuestions()).thenReturn(false);when(r.getStatus()).thenReturn(ReadinessResultStatus.GUIDE_LACK);when(sets.findBySnapshot_SnapshotIdAndInterviewMode(anyLong(),any())).thenReturn(Optional.empty());var out=service.getCompanyFitQuestionSet(1L,1L);assertThat(out.getQuestionSetId()).isNull();assertThat(out.getQuestions()).isEmpty();verify(sets,never()).save(any());verify(questions,never()).save(any());}
 @Test void generationEnabledWithoutSetIsIntegrityConflict(){when(r.isCanGenerateQuestions()).thenReturn(true);when(sets.findBySnapshot_SnapshotIdAndInterviewMode(anyLong(),any())).thenReturn(Optional.empty());assertThatThrownBy(()->service.getCompanyFitQuestionSet(1L,1L)).isInstanceOf(com.example.jobpuzzle.global.error.CustomException.class).extracting(e->((com.example.jobpuzzle.global.error.CustomException)e).getErrorCode()).isEqualTo(com.example.jobpuzzle.global.error.ErrorCode.JSON05_RESULT_INTEGRITY_CONFLICT);}
 @Test void notCompletedUsesExistingNotReadyError(){ReflectionTestUtils.setField(c,"status",AnalysisCaseStatus.ANALYZING);assertThatThrownBy(()->service.getCompanyFitQuestionSet(1L,1L)).isInstanceOf(com.example.jobpuzzle.global.error.CustomException.class).extracting(e->((com.example.jobpuzzle.global.error.CustomException)e).getErrorCode()).isEqualTo(com.example.jobpuzzle.global.error.ErrorCode.ANALYSIS_CASE_NOT_READY);}
}
